"""Triton implementation of the functional ``aten::_foreach_ceil``.

Contract (from the authoritative Gems pytest):
  * ``run(values)`` with ``values`` a list of tensors -> list of newly allocated
    ceil results, same shape / dtype, fresh storage.
  * floating dtypes fp16/bf16/fp32 are computed as ``ceil(x)`` (exact).
  * integer dtypes are supported by ATen on this backend and ``ceil`` is the
    identity for them, so they are copied through unchanged.
  * an empty list raises ``RuntimeError``; complex64 / bool / float64 raise
    ``RuntimeError`` exactly like ATen on this backend.

Launch strategy: dense tensors are bucketed by ``(dtype, numel)`` so one
homogeneous list costs one launch instead of one per tensor.  Two fused forms:
  * small buckets (``numel <= _TINY_NUMEL``): grid = ``cdiv(numel, BLOCK)`` and
    each program applies the tile body to every slot through constexpr ``K``
    guards, so there is no runtime slot ladder and no ``pid // tiles`` division
    (the profile showed the tiny bucket is AIV-scalar/control bound, 0.83, not
    bandwidth or vector bound);
  * larger buckets: grid = ``K * cdiv(numel, BLOCK)`` with slot = ``pid // tiles``
    and a uniform slot branch, which amortises the dispatch over many tiles.
Dense tensors occupy the contiguous storage range ``[0, numel)`` relative to
``data_ptr()``, so a flat pass over the storage is exact and coalesced; only
genuinely irregular layouts (holes / overlapping strides) use the strided
kernel with a contiguous output.  The flat kernels carry a bounded autotune
list over per-program tile size and num_warps because the measured limit on the
large streams is MTE2 GM->UB transfer granularity (bytes per program).

When the host proves ``numel`` is divisible by the largest candidate BLOCK it
passes ``IS_EVEN=True``, which selects an unpredicated load/store: the mask,
its compare and the masked-access lowering are pure overhead on the streaming
workloads, all of whose sizes are powers of two.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 1024
_NUM_WARPS = 4
_MAX_DIMS = 8
_KSLOTS = 16
_TINY_NUMEL = 16384

_FLOAT_DTYPES = frozenset((torch.float16, torch.bfloat16, torch.float32))
_INT_DTYPES = frozenset(
    (torch.int8, torch.uint8, torch.int16, torch.int32, torch.int64)
)

_FLAT_CONFIGS = [
    triton.Config({"BLOCK": block}, num_warps=warps)
    for block in (1024, 2048, 4096, 8192, 16384)
    for warps in (4, 8)
]
_FLAT_MAX_BLOCK = 16384

# Small tile cap keeps the 16 inlined slot bodies inside the UB budget.
_TINY_CONFIGS = [triton.Config({"BLOCK": block}, num_warps=4) for block in (256, 1024)]
_TINY_MAX_BLOCK = 1024


@triton.jit
def _ceil_tile(xp, op, offs, n, IS_FLOAT: tl.constexpr, IS_EVEN: tl.constexpr):
    if IS_EVEN:
        x = tl.load(xp + offs)
    else:
        mask = offs < n
        x = tl.load(xp + offs, mask=mask, other=0)
    if IS_FLOAT:
        # Exact in the operand dtype: a 16-bit value with |x| >= 1024 (fp16) or
        # >= 256 (bf16) is already an integer, and below that ceil(x) is an
        # integer no larger than that bound, hence exactly representable.
        y = tl.ceil(x)
    else:
        y = x
    if IS_EVEN:
        tl.store(op + offs, y)
    else:
        mask = offs < n
        tl.store(op + offs, y, mask=mask)


@triton.autotune(configs=_FLAT_CONFIGS, key=["n"])
@triton.jit
def _ceil_flat_kernel(
    x_ptr,
    o_ptr,
    n,
    IS_FLOAT: tl.constexpr,
    IS_EVEN: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    _ceil_tile(x_ptr, o_ptr, offs, n, IS_FLOAT, IS_EVEN)


