@triton.jit
def _ceil_strided_kernel(
    x_ptr,
    o_ptr,
    n,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    t0,
    t1,
    t2,
    t3,
    t4,
    t5,
    t6,
    t7,
    IS_FLOAT: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    idx = pid * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n
    v = tl.where(mask, idx, 0)
    i0 = v % s0
    r = v // s0
    i1 = r % s1
    r = r // s1
    i2 = r % s2
    r = r // s2
    i3 = r % s3
    r = r // s3
    i4 = r % s4
    r = r // s4
    i5 = r % s5
    r = r // s5
    i6 = r % s6
    i7 = r // s6
    off = i0 * t0 + i1 * t1 + i2 * t2 + i3 * t3 + i4 * t4 + i5 * t5 + i6 * t6 + i7 * t7
    x = tl.load(x_ptr + off, mask=mask, other=0)
    if IS_FLOAT:
        # Exact in the operand dtype: a 16-bit value with |x| >= 1024 (fp16) or
        # >= 256 (bf16) is already an integer, and below that ceil(x) is an
        # integer no larger than that bound, hence exactly representable.
        y = tl.ceil(x)
    else:
        y = x
    tl.store(o_ptr + idx, y, mask=mask)


def _is_dense(t):
    """``Tensor.is_non_overlapping_and_dense`` equivalent (not exposed here).

    True when sorting the non-unit dims by ascending stride yields exactly
    ``(1, s0, s0*s1, ...)``, i.e. the tensor occupies a contiguous block of
    ``numel`` storage slots with no overlaps and no holes.
    """
    pairs = []
    for sz, st in zip(t.shape, t.stride()):
        if int(sz) != 1:
            pairs.append((int(sz), int(st)))
    if not pairs:
        return True
    pairs = sorted(pairs, key=lambda p: p[1])
    expected = 1
    for sz, st in pairs:
        if sz == 0 or st != expected:
            return False
        expected *= sz
    return True


def _collapse(t):
    """Collapse the logical layout into at most ``_MAX_DIMS`` (size, stride) pairs."""
    dims = []
    for sz, st in zip(t.shape, t.stride()):
        sz = int(sz)
        if sz != 1:
            dims.append((sz, int(st)))
    merged = []
    for sz, st in dims:
        if merged and st == merged[-1][1] * merged[-1][0]:
            psz, pst = merged[-1]
            merged[-1] = (psz * sz, pst)
        else:
            merged.append((sz, st))
    if len(merged) > _MAX_DIMS:
        raise RuntimeError(
            "_foreach_ceil: unsupported layout with more than %d collapsed dims"
            % _MAX_DIMS
        )
    sizes = [d[0] for d in merged]
    strides = [d[1] for d in merged]
    pad = _MAX_DIMS - len(merged)
    return sizes + [1] * pad, strides + [0] * pad


def _ceil_strided(t, is_float):
    n = t.numel()
    out = torch.empty(t.shape, dtype=t.dtype, device=t.device)
    if n == 0:
        return out
    sizes, strides = _collapse(t)
    grid = (triton.cdiv(n, _BLOCK),)
    _ceil_strided_kernel[grid](
        t,
        out,
        n,
        sizes[0],
        sizes[1],
        sizes[2],
        sizes[3],
        sizes[4],
        sizes[5],
        sizes[6],
        sizes[7],
        strides[0],
        strides[1],
        strides[2],
        strides[3],
        strides[4],
        strides[5],
        strides[6],
        strides[7],
        IS_FLOAT=is_float,
        BLOCK=_BLOCK,
        num_warps=_NUM_WARPS,
    )
    return out


def _launch_group(srcs, dsts, is_float, n):
    k = len(srcs)
    if k == 1:
        _ceil_flat_kernel[lambda meta: (triton.cdiv(n, meta["BLOCK"]),)](
            srcs[0],
            dsts[0],
            n,
            IS_FLOAT=is_float,
            IS_EVEN=(n % _FLAT_MAX_BLOCK == 0),
        )
        return
    args = []
    for i in range(_KSLOTS):
        j = i if i < k else 0
        args.append(srcs[j])
        args.append(dsts[j])
    if n <= _TINY_NUMEL:
        _ceil_tiny_kernel[lambda meta: (triton.cdiv(n, meta["BLOCK"]),)](
            *args,
            n,
            K=k,
            IS_FLOAT=is_float,
            IS_EVEN=(n % _TINY_MAX_BLOCK == 0),
        )
        return
    _ceil_fused_kernel[lambda meta: (k * triton.cdiv(n, meta["BLOCK"]),)](
        *args,
        n,
        K=k,
        IS_FLOAT=is_float,
        IS_EVEN=(n % _FLAT_MAX_BLOCK == 0),
    )


def foreach_ceil(self=None, *args, **kwargs):
    tensors = self
    if tensors is None and args:
        tensors = args[0]
    if kwargs:
        if "self" in kwargs:
            tensors = kwargs.pop("self")
        elif "tensors" in kwargs:
            tensors = kwargs.pop("tensors")
        if kwargs:
            raise TypeError(
                "run() got unexpected keyword arguments: %s" % sorted(kwargs)
            )
    if isinstance(tensors, torch.Tensor):
        raise TypeError("run() expects a sequence of Tensor, got a single Tensor")
    values = list(tensors)
    if not values:
        raise RuntimeError("Tensor list must have at least one tensor.")

    outs = [None] * len(values)
    pending = []
    for i, t in enumerate(values):
        if not isinstance(t, torch.Tensor):
            raise TypeError("expected Tensor as element in argument 0")
        dtype = t.dtype
        if dtype in _FLOAT_DTYPES:
            is_float = True
        elif dtype in _INT_DTYPES:
            is_float = False
        else:
            raise RuntimeError(
                "ceil not implemented for '%s'" % str(dtype).replace("torch.", "")
            )
        if _is_dense(t):
            if t.numel() == 0:
                outs[i] = torch.empty_like(t)
            else:
                pending.append((i, t, is_float))
        else:
            outs[i] = _ceil_strided(t, is_float)

    buckets = {}
    for i, t, is_float in pending:
        outs[i] = torch.empty_like(t)
        buckets.setdefault((t.dtype, t.numel(), is_float), []).append(i)

    for (dtype, n, is_float), idxs in buckets.items():
        for start in range(0, len(idxs), _KSLOTS):
            chunk = idxs[start : start + _KSLOTS]
            _launch_group(
                [values[i] for i in chunk],
                [outs[i] for i in chunk],
                is_float,
                n,
            )
    return outs
